import { useEffect, useState } from 'react';
import { miniMap } from '../world.js';
import type { Site } from '../types';

// Only markup generated by our SVG/chart renderers belongs in this component.
// User text and API content are rendered as React text nodes elsewhere.
export function Markup({ html, className }: { html: string; className?: string }) {
  return <div className={className} dangerouslySetInnerHTML={{ __html: html }} />;
}
export function Locator({ site, large = false }: { site: Site; large?: boolean }) {
  const [html, setHtml] = useState('');
  useEffect(() => {
    let active = true;
    miniMap(site, {large}).then(markup => { if (active) setHtml(markup); }).catch(() => { if (active) setHtml('Map unavailable.'); });
    return () => { active = false; };
  }, [site, large]);
  return <Markup html={html} />;
}
